from taf.ul.ettf.utils.paths import logs_directory
from taf.ul.ettf.setups.commissioning import Commissioning, SwconfigFlags
from taf.ul.ettf.setups.radio import Iphy
from taf.ul.ettf.setups.simulator import SimulatedEnb, SimulatedGnb, SimulatedNetworkInterface, Egate, \
    REACH_ONAIR_TIMEOUT, is_egate_opened, AliveEgate
from taf.ul.ettf.setups.wts_to_ramdisk import WtsPerformance
from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.typed.custom_types import ExistingFilepath, Filepath, Ip
from taf.ul.ettf.events.notifier import Notifier
from taf.ul.ettf.events.comparator import On
from taf.ul.ettf.events.event import Teardown
from taf.ul.ettf.events.lifetime_policy import OneTimeCall
from taf.ul.ettf.utils.provider import disabled_on_any, VARIABLES, is_keep_alive_enabled
from taf.ul.ettf.logger import custom_logger


notifier = Notifier()
conditionally_disabled = disabled_on_any(VARIABLES.CONFIG_DISABLED)
logger = custom_logger('Setups_Interface')


class Setups(object):
    @conditionally_disabled
    @typed(commissioning=Filepath(), remote_host=Ip())
    def with_gnb_configuration(self, commissioning, remote_host=None):
        Commissioning(logs_directory()).perform(commissioning, remote_host)

    @conditionally_disabled
    def with_iphy_configuration(self, config, yaml_filename=None):
        Iphy(config, logs_directory(), yaml_filename=yaml_filename).configure()

    @typed(remote_host=Ip())
    def with_swconfig_flags(self, flags, remote_host=None):
        swconfig_flags = SwconfigFlags(logs_directory())
        swconfig_flags.set(flags, remote_host)
        notifier.register(swconfig_flags.sw_config_flags_teardown, On(Teardown), OneTimeCall())

    def with_simulated_enb(self):
        simulated_enb = SimulatedEnb()
        simulated_enb.start()
        notifier.register(simulated_enb.simulated_enb_teardown, On(Teardown), OneTimeCall())

    def with_simulated_gnb(self, ip=None):
        simulated_gnb = SimulatedGnb(ip=ip)
        simulated_gnb.start()
        notifier.register(simulated_gnb.simulated_gnb_teardown, On(Teardown), OneTimeCall())

    def with_simulated_network_interface(self, ip=None, name=None):
        simulated_gnb = SimulatedNetworkInterface(ip=ip, name=name)
        simulated_gnb.start()
        notifier.register(simulated_gnb.simulated_interface_teardown, On(Teardown), OneTimeCall())

    def with_wts_on_ramdisk(self):
        wts = WtsPerformance()
        wts.relocate_to_ramdisk()
        if not is_keep_alive_enabled():
            notifier.register(wts.wts_performance_teardown, On(Teardown), OneTimeCall())

    @typed(config=ExistingFilepath(), timeout=int, remote_hosts=list)
    def with_simulator_configuration(self, config, timeout=REACH_ONAIR_TIMEOUT, remote_hosts=None):
        simulator = self._create_simulator(config)

        try:
            simulator.reach_onair(remote_hosts=remote_hosts, timeout=timeout)
        finally:
            if not is_keep_alive_enabled():
                notifier.register(simulator.teardown, On(Teardown), OneTimeCall())

    def _try_wts_relocation(self):
        try:
            self.with_wts_on_ramdisk()
        except Exception:
            logger.debug('Relocation WTS to ramdisk failed')

    def _create_simulator(self, config):
        if is_keep_alive_enabled() and is_egate_opened():
            return AliveEgate()

        simulator = Egate(config, logs_directory())

        if is_keep_alive_enabled():
            logger.info('Simulator session will be alive after tests execution')
            simulator.keep_alive()

        return simulator


setups = Setups
